import java.io.*;
import java.net.URL;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class GoodServlet extends HttpServlet {
    public void doGet(HttpServletRequest request, HttpServletResponse response) {
        // Fixed: URL-encode the user input to prevent injection
        String searchTerm = request.getParameter("search");
        String encodedTerm = URLEncoder.encode(searchTerm, "UTF-8");
        String urlString = "https://example.com/search?q=" + encodedTerm;
        URL url = new URL(urlString);
        try {
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setConnectTimeout(5000);
            conn.setReadTimeout(5000);
            int responseCode = conn.getResponseCode();
            if (responseCode == 200) {
                System.out.println("Response Code: " + responseCode);
            }
        } catch (Exception e) {
            // Handle exceptions properly to avoid information disclosure
            e.printStackTrace();
        } finally {
            // Ensure the connection is closed
            if (conn != null) {
                conn.close();
            }
        }
    }
}
